import {estimateBF,prepareRecord} from './calculations.js';
import {journeyComparison} from './journey-model.js';
const fmt=n=>new Intl.NumberFormat('pt-BR',{maximumFractionDigits:2}).format(n),date=s=>s.split('-').reverse().join('/'),sign=n=>(n>0?'+':'')+fmt(n);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const labels={improved:'Melhorou para o objetivo',worsened:'Piorou para o objetivo',maintained:'Se manteve',unrated:'Sem objetivo definido','equal-distance':'Mesma distância da meta',missing:'Sem dados comparáveis',incompatible:'Método não comparável'};
export function mountJourney({fatPanel,journeyPanel,getRecords,getGoals,isDemo}){
  let directions={},filter='all';
  const overview=document.createElement('section');overview.className='panel';overview.id='fat-overview';fatPanel.prepend(overview);
  journeyPanel.innerHTML='<section class="panel journey-comparison"><div class="panel-head"><div><p class="eyebrow">A VISÃO COMPLETA DO SEU PROJETO</p><h2>Do início até hoje.</h2></div><span class="pill">PRIMEIRA → ÚLTIMA POR DATA</span></div><p id="journey-dates"></p><p class="muted">Esta comparação usa sempre a avaliação mais antiga e a mais recente, independentemente do período escolhido nas outras abas. Medidas ausentes nas pontas não são substituídas por registros intermediários.</p><div id="journey-empty" class="empty"></div><div id="journey-content"><div id="journey-totals" class="journey-totals" aria-live="polite"></div><div class="journey-controls"><label>Mostrar<select id="journey-filter"><option value="all">Todos os dados</option><option value="improved">Melhoraram para o objetivo</option><option value="worsened">Pioraram para o objetivo</option><option value="maintained">Se mantiveram</option><option value="unrated">Sem objetivo definido</option><option value="equal-distance">Mesma distância da meta</option><option value="missing">Sem comparação disponível</option></select></label><button type="button" class="quiet" id="journey-reset">Usar minhas metas salvas</button></div><p class="muted">“Melhorou” significa aproximar-se do objetivo escolhido, não um diagnóstico de saúde ou de ganho muscular. Usamos sua meta mais recente para cada medida; você pode trocar o critério abaixo só para esta sessão. Para manter um alvo entre acessos, cadastre-o em Metas.</p><div class="table-wrap"><table class="journey-table"><thead><tr><th>Medida</th><th>Primeira</th><th>Última</th><th>Mudança</th><th>Objetivo da comparação</th><th>Leitura</th></tr></thead><tbody id="journey-rows"></tbody></table></div><p id="journey-filter-empty" class="empty" hidden>Nenhuma medida corresponde a este filtro.</p><details><summary>Precisão, método e interpretação</summary><p>“Se manteve” indica valores numéricos iguais, considerando apenas tolerância de arredondamento computacional. Pequenas diferenças podem refletir a medição. Se um número parece igual após arredondar, a classificação ainda usa o valor completo. BF é comparado em pontos percentuais (p.p.); por exemplo, 20% → 18% significa −2 p.p., ou −10% de variação relativa.</p><p>BF informado manualmente ou obtido por equações diferentes aparece sem classificação por objetivo, pois o método não pode ser confirmado. Massa de gordura e massa livre de gordura são derivadas do peso e do BF calculado por dobras; massa livre de gordura não equivale a músculo.</p><p>“Manter o valor inicial” considera qualquer mudança como afastamento desse valor. Com meta numérica, comparamos as distâncias ao alvo; atravessar o alvo não é automaticamente uma melhora. Dois valores diferentes igualmente distantes da meta não contam como “se manteve”.</p></details><details><summary>Observações da primeira e da última avaliação</summary><div id="journey-notes"></div></details></div></section>';
  journeyPanel.querySelector('#journey-filter').onchange=e=>{filter=e.target.value;renderComparison();};
  journeyPanel.querySelector('#journey-reset').onclick=()=>{directions={};renderComparison();};
  journeyPanel.querySelector('#journey-rows').onchange=e=>{const select=e.target.closest('[data-direction]');if(select){directions[select.dataset.direction]=select.value;const key=select.dataset.direction;renderComparison();journeyPanel.querySelector(`[data-direction="${key}"]`)?.focus();}};
  function renderFat(){const records=getRecords(),first=records.find(r=>r.id===document.querySelector('#from').value),last=records.find(r=>r.id===document.querySelector('#to').value);
    function figure(r,title){const record=r?prepareRecord(r):null,result=record?estimateBF(record):null,bf=record?.fat;const has=Number.isFinite(bf),percent=has?Math.min(100,Math.max(0,bf)):0;
      return `<article class="fat-person"><p class="eyebrow">${title}${r?' · '+date(r.date):''}</p><svg viewBox="0 0 260 300" role="img" aria-label="${has?fmt(bf)+'% de gordura corporal total':'BF não disponível'}"><circle class="fat-ring-track" cx="130" cy="134" r="112"/><circle class="fat-ring-value" cx="130" cy="134" r="112" pathLength="100" stroke-dasharray="${percent} 100" transform="rotate(-90 130 134)"/><g class="fat-silhouette" transform="translate(68 44) scale(.52)"><circle cx="120" cy="36" r="24"/><path d="M85 77L59 87L30 209L51 217L87 132ZM155 77L181 87L210 209L189 217L153 132ZM91 73H149L158 151L151 216H89L82 151ZM89 222H116L111 354H78ZM124 222H151L162 354H129Z"/></g><text x="130" y="287" text-anchor="middle">${has?fmt(bf)+'%':'—'}</text></svg><p>${result?.status==='ok'?'BF total estimado · sete dobras':has?'BF informado · método não registrado':'Complete as dobras ou informe o BF na avaliação.'}</p></article>`;
    }
    overview.innerHTML=`<div class="panel-head"><div><p class="eyebrow">GORDURA CORPORAL, EM PERSPECTIVA</p><h2>Seu BF antes e depois.</h2></div><span class="pill">PERCENTUAL TOTAL</span></div><div class="fat-people">${figure(first,'Inicial')}${figure(last,'Final')}</div><p class="muted">O anel representa o percentual de gordura do corpo inteiro. O boneco não localiza essa gordura nem reproduz sua aparência. Abaixo, explore as dobras em milímetros: elas não permitem calcular um percentual de gordura para cada região.</p>`;
  }
  function renderComparison(){const result=journeyComparison(getRecords(),isDemo()?[]:getGoals(),directions),empty=journeyPanel.querySelector('#journey-empty');journeyPanel.querySelector('#journey-content').hidden=!result;empty.hidden=!!result;
    if(!result){empty.textContent='Cadastre pelo menos duas avaliações em datas diferentes para acompanhar o resultado desde o início.';journeyPanel.querySelector('#journey-dates').textContent='';journeyPanel.querySelector('#journey-rows').replaceChildren();journeyPanel.querySelector('#journey-notes').replaceChildren();return;}
    const {first,last,duration,rows}=result;journeyPanel.querySelector('#journey-dates').textContent=`${date(first.date)} → ${date(last.date)} · ${duration} dias · ${getRecords().length} avaliações${isDemo()?' · Dados fictícios':''}`;
    journeyPanel.querySelector('#journey-totals').innerHTML=[['improved','Melhoraram'],['worsened','Pioraram'],['maintained','Se mantiveram'],['unrated','Sem objetivo'],['equal-distance','Mesma distância'],['missing','Sem comparação']].map(([key,title])=>`<div class="journey-count ${key}"><strong>${rows.filter(r=>key==='missing'?['missing','incompatible'].includes(r.status):r.status===key).length}</strong><span>${title}</span></div>`).join('');
    const visible=rows.filter(r=>filter==='all'||filter==='missing'&&['missing','incompatible'].includes(r.status)||r.status===filter);
    journeyPanel.querySelector('#journey-filter-empty').hidden=visible.length>0;
    journeyPanel.querySelector('#journey-rows').innerHTML=visible.map(r=>`<tr><th scope="row">${r.label}</th><td>${Number.isFinite(r.start)?fmt(r.start)+' '+r.unit:'—'}</td><td>${Number.isFinite(r.end)?fmt(r.end)+' '+r.unit:'—'}</td><td>${r.change!=null?`${sign(r.change)} ${r.key==='fat'?'p.p.':r.unit}<small>${r.relative!=null?sign(r.relative)+'% de variação relativa':''}</small>`:'—'}</td><td><select data-direction="${r.key}" aria-label="Objetivo para ${r.label}">${[['goal',Number.isFinite(r.target)?'Meta: '+fmt(r.target)+' '+r.unit:'Meta salva / sem meta'],['increase','Aumentar'],['decrease','Reduzir'],['maintain','Manter valor inicial'],['neutral','Só observar']].map(([value,label])=>`<option value="${value}"${r.choice===value?' selected':''}>${label}</option>`).join('')}</select></td><td><span class="journey-badge ${r.status}">${labels[r.status]}</span>${r.status==='unrated'?`<small>${r.change>0?'Aumentou':'Diminuiu'}; escolha um objetivo.</small>`:''}</td></tr>`).join('');
    journeyPanel.querySelector('#journey-notes').innerHTML=[['Primeira',first],['Última',last]].map(([title,r])=>`<h3>${title} · ${date(r.date)}</h3><p>${esc(r.notes)||'Sem observações.'}</p><p>${esc([r.context?.time,r.context?.conditions].filter(Boolean).join(' · '))}</p>`).join('');
  }
  return {refresh(){renderFat();renderComparison();},reset(){directions={};filter='all';journeyPanel.querySelector('#journey-filter').value='all';renderFat();renderComparison();}};
}
